mapper.select:
select mori.refund_item_id as refundItemId, mori.refund_id as refundId, mor.refund_no as refundNo, mori.order_id as orderId, mori.order_item_id as orderItemId, moi.product_name as productName, moi.sku_name as skuName, mori.refund_quantity as refundQuantity, mori.refund_amount as refundAmount, mori.del_flag as delFlag, mori.create_time as createTime, mori.update_time as updateTime from mall_order_refund_item mori left join mall_order_refund mor on mori.refund_id = mor.refund_id and mor.del_flag = 0 left join mall_order_item moi on mori.order_item_id = moi.order_item_id and moi.del_flag = 0 where mori.del_flag = 0
and mori.refund_id = #{refundId}
and mor.refund_no like concat('%', #{refundNo}, '%')
and mori.order_id = #{orderId}
and mori.order_item_id = #{orderItemId}
and moi.product_name like concat('%', #{productName}, '%')
order by mori.refund_item_id desc

select mori.refund_item_id as refundItemId, mori.refund_id as refundId, mori.order_id as orderId, mori.order_item_id as orderItemId, mori.refund_quantity as refundQuantity, mori.refund_amount as refundAmount, mori.del_flag as delFlag, mori.create_time as createTime, mori.update_time as updateTime from mall_order_refund_item mori where mori.del_flag = 0
and mori.refund_id = #{refundId}
and mori.order_id = #{orderId}
and mori.order_item_id = #{orderItemId}
order by mori.refund_item_id desc

select count(1)
from mall_order_refund_item mori
where mori.del_flag = 0

    and mori.refund_id = #{refundId}


    and mori.order_id = #{orderId}


    and mori.order_item_id = #{orderItemId}

select mori.refund_item_id, mori.refund_id, mori.order_id, mori.order_item_id, mori.refund_quantity, mori.refund_amount, mori.del_flag, mori.create_time, mori.update_time from mall_order_refund_item mori where mori.del_flag = 0
and mori.refund_id = #{refundId}
and mori.order_id = #{orderId}
and mori.order_item_id = #{orderItemId}
order by mori.refund_item_id desc limit 1

mapper.update:
update mall_order_refund_item
set del_flag = 1
where refund_item_id = #{refundItemId}
